import { EventEmitter } from 'node:events'
import type { AgentProviderKey } from './agent-provider-key'
import type {
  AgentIdentityWorkerRequest,
  AgentIdentityWorkerResponse
} from './agent-identity-worker-protocol'
import type { WorkerRequestTransport } from '../../worker-threads/worker-thread-transport'
import type { AgentIdentityClient, AgentIdentityLookup } from './agent-identity-worker-client'
import { handleAgentIdentityRequest } from './agent-identity-worker-entry'
import { isOrcaSessionId } from '../../../shared/agent-session/identity/orca-session-address'

/** The worker's real SQL handler behind an asynchronous boundary, counting requests. Each answer
 *  can be held so a test decides when (and in which order) replies arrive. */
export class InProcessAgentIdentityClient implements AgentIdentityClient {
  identifyRequests = 0
  hasRequests = 0
  /** When set, `identify` waits for `release()` before answering. */
  hold = false
  /** Answers the next N identify requests as unavailable after running their SQL. */
  failAfterCommit = 0
  private held: (() => void)[] = []

  async identify(path: string, key: AgentProviderKey): Promise<AgentIdentityLookup> {
    this.identifyRequests++
    if (this.hold) {
      await new Promise<void>((resolve) => this.held.push(resolve))
    }
    const response = handleAgentIdentityRequest({ id: 0, kind: 'identify', path, key })
    if (!response.ok || this.failAfterCommit-- > 0) {
      return undefined
    }
    const value = response.value
    return value === null
      ? { id: null }
      : typeof value === 'string' && isOrcaSessionId(value)
        ? { id: value }
        : undefined
  }

  async has(path: string, orcaSessionId: string): Promise<boolean | undefined> {
    this.hasRequests++
    const response = handleAgentIdentityRequest({ id: 0, kind: 'has', path, orcaSessionId })
    return response.ok && typeof response.value === 'boolean' ? response.value : undefined
  }

  /** Lets every held request answer, oldest first. */
  release(): void {
    for (const resolve of this.held.splice(0)) {
      resolve()
    }
  }

  readonly isRetiring = false

  retired(): Promise<void> {
    return Promise.resolve()
  }

  dispose(): void {}
}

type ScriptedAnswer = AgentIdentityWorkerResponse | 'never'

/** Fake identity worker threads behind the real client and request queue: each request is
 *  answered after `serviceMs` by `answer`, and exits can be held to prove no worker starts
 *  beside a retiring one. */
export class ScriptedIdentityWorkers {
  readonly posts: AgentIdentityWorkerRequest[] = []
  spawns = 0
  live = 0
  maxLive = 0
  serviceMs = 0
  spawnFails = false
  holdExit = false
  readonly known = new Set<string>()
  answer: (request: AgentIdentityWorkerRequest) => ScriptedAnswer = (request) =>
    request.kind === 'identify'
      ? { id: request.id, ok: true, value: `claude_${request.key.providerSessionId}` }
      : { id: request.id, ok: true, value: this.known.has(request.orcaSessionId) }
  private readonly exits: (() => void)[] = []

  readonly factory = (): WorkerRequestTransport => {
    if (this.spawnFails) {
      throw new Error('identity worker could not start')
    }
    this.spawns++
    this.live++
    this.maxLive = Math.max(this.maxLive, this.live)
    const worker = new EventEmitter()
    let exited = false
    const exit = (): void => {
      if (!exited) {
        exited = true
        this.live--
        worker.emit('exit', 1)
      }
    }
    return Object.assign(worker, {
      unref: () => {},
      postMessage: (request: AgentIdentityWorkerRequest) => {
        this.posts.push(request)
        const reply = this.answer(request)
        if (reply !== 'never') {
          setTimeout(() => !exited && worker.emit('message', reply), this.serviceMs)
        }
      },
      terminate: () =>
        new Promise<number>((resolve) => {
          const done = (): void => {
            exit()
            resolve(1)
          }
          if (this.holdExit) {
            this.exits.push(done)
          } else {
            queueMicrotask(done)
          }
        })
    })
  }

  identifyPosts(): number {
    return this.posts.filter((post) => post.kind === 'identify').length
  }

  releaseExits(): void {
    for (const exit of this.exits.splice(0)) {
      exit()
    }
  }
}

import { mkdtemp, rm, writeFile } from 'node:fs/promises'
import { join } from 'node:path'
import { tmpdir } from 'node:os'
import { afterEach, beforeEach, describe, expect, it, vi } from 'vitest'

const mocks = vi.hoisted(() => ({
  callRuntimeEnvironment: vi.fn(),
  downloadSkillPackageGrant: vi.fn()
}))

vi.mock('../../ipc/runtime-environments/requests/runtime-environment-transport-routing', () => ({
  callRuntimeEnvironment: mocks.callRuntimeEnvironment
}))
vi.mock('../package-download/skill-package-download', () => ({
  downloadSkillPackageGrant: mocks.downloadSkillPackageGrant
}))

import { transferSkillPackageToRuntime } from './skill-client-mediated-transfer'

describe('transferSkillPackageToRuntime', () => {
  let root = ''

  beforeEach(async () => {
    root = await mkdtemp(join(tmpdir(), 'orca-skill-transfer-test-'))
    mocks.callRuntimeEnvironment.mockReset()
    mocks.downloadSkillPackageGrant.mockReset()
  })

  afterEach(async () => {
    await rm(root, { recursive: true, force: true })
  })

  it('cancels the begun session when cancellation arrives before chunking', async () => {
    const archivePath = join(root, 'package.tar.gz')
    await writeFile(archivePath, Buffer.from('package-data'))
    const cleanup = vi.fn(async () => undefined)
    const controller = new AbortController()
    mocks.downloadSkillPackageGrant.mockResolvedValue({ archivePath, cleanup })
    mocks.callRuntimeEnvironment.mockImplementation(
      async (_userData: string, _environment: string, method: string) => {
        if (method === 'skills.beginUpload') {
          controller.abort()
          return {
            id: 'rpc-begin',
            ok: true,
            result: { uploadId: 'upload-1', chunkBytes: 256 * 1024 },
            _meta: { runtimeId: 'runtime-1' }
          }
        }
        return {
          id: 'rpc-cancel',
          ok: true,
          result: undefined,
          _meta: { runtimeId: 'runtime-1' }
        }
      }
    )

    await expect(
      transferSkillPackageToRuntime({
        userDataPath: root,
        environmentId: 'environment-1',
        transferId: 'operation-1',
        package: {
          packageId: 'package-1',
          versionId: 'version-1',
          packageDigest: 'a'.repeat(64),
          archiveSha256: 'b'.repeat(64),
          compressedBytes: 12
        },
        grant: {
          url: 'https://storage.googleapis.com/bucket/package.tar.gz',
          expiresAt: '2099-01-01T00:00:00.000Z'
        },
        requireHttps: true,
        signal: controller.signal
      })
    ).rejects.toThrow('skill-install-cancelled')
    expect(cleanup).toHaveBeenCalledOnce()
    expect(mocks.callRuntimeEnvironment).toHaveBeenCalledWith(
      root,
      'environment-1',
      'skills.cancelUpload',
      { uploadId: 'upload-1' },
      15_000
    )
  })
})

import { randomUUID } from 'node:crypto'
import {
  isOrcaSessionId,
  type OrcaSessionId
} from '../../../../shared/agent-session/identity/orca-session-address'
import type { AgentProviderKey } from '../../identity/agent-provider-key'
import type {
  AgentIdentityClient,
  AgentIdentityLookup
} from '../../identity/agent-identity-worker-client'
import { AgentHookServerAgentIdentities } from '../server-agent-identities'

/** An identity store held in memory: one stable id per key and store path, answered
 *  asynchronously, with no worker thread or file. */
export class MemoryAgentIdentityClient implements AgentIdentityClient {
  private readonly ids = new Map<string, OrcaSessionId>()

  async identify(path: string, key: AgentProviderKey): Promise<AgentIdentityLookup> {
    const keyString = JSON.stringify([path, key])
    const id = this.ids.get(keyString) ?? `${key.agent}_${randomUUID()}`
    if (!isOrcaSessionId(id)) {
      return undefined
    }
    this.ids.set(keyString, id)
    return { id }
  }

  async has(path: string, orcaSessionId: string): Promise<boolean> {
    const pathPrefix = JSON.stringify([path]).slice(0, -1)
    return [...this.ids].some(([key, id]) => id === orcaSessionId && key.startsWith(pathPrefix))
  }

  readonly isRetiring = false

  retired(): Promise<void> {
    return Promise.resolve()
  }

  dispose(): void {}
}

// Hook-server suites run from source, where the identity worker has no built entry; the worker's
// own suites cover it. Every hook-server owner these suites start gets an in-memory store.
Reflect.set(
  AgentHookServerAgentIdentities.prototype,
  'createAgentIdentityClient',
  () => new MemoryAgentIdentityClient()
)

import { expect, it } from 'vitest'
import { agentSessionRecordFixture } from '../../../native-chat/testing/agent-session-record-test-fixture'
import { agentSessionConversationView } from '../../../../shared/agent-session/lifecycle/leases/agent-session-conversation-view'
import {
  isOrcaSessionId,
  formatOrcaSessionAddress
} from '../../../../shared/agent-session/identity/orca-session-address'
import { testOrcaSessionId } from '../../../../shared/agent-session/identity/orca-session-address-test-fixture'
import { CrewReadModel } from './crew-read-model'
import { fixture } from './crew-read-model.test-fixture'
import { createCrewPartyRegistry } from './crew-parties'
import { createCrewRecipientInputs } from './crew-recipient-inputs'

import { LEGACY_CONTRACT_VERSION } from '../db/contract-constants'
import { ORCHESTRATION_LEGACY_RUN_ID as LEGACY_RUN_ID } from '../../../../shared/orchestration/orchestration-rpc-contract'

import { subscribeCrew } from './crew-stream'

const LOCAL = testOrcaSessionId('aaaaaaaa-1111-4111-8111-aaaaaaaaaaaa')
const IMPORTED = testOrcaSessionId('bbbbbbbb-2222-4222-8222-bbbbbbbbbbbb')
const record = (sessionId: string) =>
  agentSessionConversationView(agentSessionRecordFixture({ sessionId }))

function authorityFixture() {
  const f = fixture()
  const records = new Map<string, ReturnType<typeof record>>(
    [LOCAL, IMPORTED].map((id) => [id, record(id)])
  )
  records.delete(IMPORTED)
  const visible = new Set([LOCAL])
  f.deps.records = {
    listRecords: () => [...records.values()],
    getRecord: (id) => records.get(id) ?? null,
    getVisibleSessionTabIndex: () => ({ present: true, sessionIds: [...visible] })
  }
  const input = () => {
    const registry = createCrewPartyRegistry(f.deps)
    return createCrewRecipientInputs(f.db, registry.records, registry.commandCanonical, () =>
      f.db.getLegacyAdoptedRunMailboxOwner()
    )
  }
  const available = (ids: string[], senderRun?: string) => {
    const selected = ids.filter(isOrcaSessionId)
    const facts = input()
    facts.prepare(selected)
    return facts.finish(selected, senderRun, { livePane: () => null, process: () => null })
  }
  return { ...f, records, visible, input, available }
}

it('re-derives retained legacy custody on actual commit/revoke/reset writers', async () => {
  const f = authorityFixture()
  const peer = formatOrcaSessionAddress(IMPORTED)
  // Retained adoption-table control; migration admission remains covered by the existing legacy fixtures.
  f.db.db
    .prepare(
      'INSERT INTO legacy_adoptions (source_run_id, adopted_run_id, scheduler_state_lost, adopted_at) VALUES (?, ?, 1, ?)'
    )
    .run(LEGACY_RUN_ID, f.run.id, '2099-01-01 00:00:00')
  f.db.db
    .prepare(
      "INSERT INTO coordinator_runs (id, spec, status, coordinator_handle, scheduler_lost_at) VALUES (?, ?, 'failed', ?, ?)"
    )
    .run('retained-c2', 'retained coordinator', peer, '2099-01-01 00:00:00')
  const task = f.db.createTask({ runId: f.run.id, spec: 'active individual route' })
  const dispatch = f.db.createDispatchContext({
    taskId: task.id,
    assigneeHandle: formatOrcaSessionAddress(LOCAL),
    creator: { kind: 'system' },
    maxDepth: 10
  })
  const facts = f.input()
  facts.prepare([LOCAL, IMPORTED])
  const allowed = facts.finish([LOCAL, IMPORTED], undefined, {
    livePane: () => null,
    process: () => null
  })
  expect(allowed(LOCAL)).toBe(true)
  expect(allowed(IMPORTED)).toBe(true)
  f.db.db
    .prepare('UPDATE dispatch_contexts SET contract_version = ? WHERE id = ?')
    .run(LEGACY_CONTRACT_VERSION, dispatch.id)
  f.db.insertMessage({
    from: peer,
    to: 'term_worker',
    subject: 'retained target',
    body: 'retained target'
  })
  const model = new CrewReadModel(() => f.deps, f.db.crewChanges.subscribe)
  const stop = subscribeCrew(
    () => model.read('term_worker'),
    model.subscribe,
    () => {}
  )
  try {
    const row = () =>
      model
        .read('term_worker')
        .sections.talkingWith.find((row) => row.latest?.preview === 'retained target')
    expect(row()?.sendAddress).toBe(peer)
    const principal = f.db.commitLegacyCompatibilityPrincipal({
      runId: f.run.id,
      dispatchId: dispatch.id,
      role: 'worker',
      hostScope: 'local:fixture',
      terminalHandle: peer,
      paneKey: 'legacy:aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaaa',
      launchTokenHash: 'fixture-only',
      processIncarnation: 'fixture-only'
    })
    await Promise.resolve()
    expect(row()).not.toHaveProperty('sendAddress')
    f.db.setLegacyCompatibilityPrincipalStatus(principal.principal.id, 'revoked')
    await Promise.resolve()
    expect(row()?.sendAddress).toBe(peer)
    f.db.setLegacyCompatibilityPrincipalStatus(principal.principal.id, 'revoked')
    await Promise.resolve()
    f.db.resetMessages()
    await Promise.resolve()
    expect(model.read('term_worker').sections.talkingWith).toEqual([])
  } finally {
    stop()
  }
})

import { agentSessionRecordFixture } from '../../../native-chat/testing/agent-session-record-test-fixture'
import { agentSessionConversationView } from '../../../../shared/agent-session/lifecycle/leases/agent-session-conversation-view'
import { testOrcaSessionId } from '../../../../shared/agent-session/identity/orca-session-address-test-fixture'
import { formatOrcaSessionAddress as address } from '../../../../shared/agent-session/identity/orca-session-address'
import { fixture } from './crew-read-model.test-fixture'

export const SELF = testOrcaSessionId('aaaaaaaa-1111-4111-8111-aaaaaaaaaaaa')
export const TARGET = testOrcaSessionId('bbbbbbbb-2222-4222-8222-bbbbbbbbbbbb')

export const crewRecord = (sessionId: string) =>
  agentSessionConversationView(agentSessionRecordFixture({ sessionId }))

export function deltaFixture(peers = 0) {
  const f = fixture()
  const records = new Map([[SELF.toString(), crewRecord(SELF)]])
  for (let i = 0; i < peers; i++) {
    const id = testOrcaSessionId(`chat-delta-${i}`)
    records.set(id, crewRecord(id))
    f.db.insertMessage({ from: address(id), to: address(SELF), subject: 'Peer', body: `peer ${i}` })
  }
  const visible = new Set(records.keys())
  f.deps.records = {
    listRecords: () => [...records.values()],
    getRecord: (id) => records.get(id) ?? null,
    getVisibleSessionTabIndex: () => ({ present: true, sessionIds: [...visible] })
  }
  return { ...f, records, visible }
}

export function remembered(f: ReturnType<typeof deltaFixture>, id = TARGET, count = 2) {
  const runs = Array.from({ length: count }, (_, i) =>
    f.db.createRun({
      objective: `history ${i}`,
      coordinatorHandle: null,
      coordinatorPaneKey: null,
      coordinatorOrcaSessionId: id
    })
  )
  f.db.unbindOtherRunsForCoordinator(
    { terminalHandle: null, paneKey: null, orcaSessionId: id },
    f.run.id
  )
  return runs
}

import { vi } from 'vitest'
import type Database from '../../../sqlite/sync-database'
import type { SqliteBindings, SqliteRow } from '../../../sqlite/sqlite-statement'

export function selectedKeyMultiplier(sql: string): number {
  return sql.includes('AS recorded')
    ? 2
    : sql.includes("'handle' AS branch")
      ? 3
      : sql.includes('candidates AS (')
        ? 2
        : sql.includes('coordinator.run_id FROM json_each')
          ? 1
          : 0
}

export type CrewSqlExecution = {
  phase: string
  sql: string
  parameters: SqliteBindings
  method: 'all' | 'get' | 'run' | 'iterate'
  rows: number
  stringChars: number
  results: SqliteRow[]
  chars: number
  bytes: number
  keys: number
  requestChars: number
  failed: boolean
}

export function meterCrewSql(db: Database.Database) {
  const executions: CrewSqlExecution[] = []
  const control: { phase: string; before?: (sql: string) => void } = { phase: 'trigger' }
  const prepare = db.prepare.bind(db)
  const spy = vi.spyOn(db, 'prepare').mockImplementation((sql) => {
    const statement = prepare(sql)
    const begin = (method: CrewSqlExecution['method'], parameters: SqliteBindings) => {
      const multiplier = selectedKeyMultiplier(sql)
      const requested: unknown =
        multiplier && typeof parameters[0] === 'string' ? JSON.parse(parameters[0]) : null
      const entry: CrewSqlExecution = {
        phase: control.phase,
        sql,
        parameters,
        method,
        rows: 0,
        stringChars: 0,
        results: [],
        chars: 0,
        bytes: 0,
        keys: Array.isArray(requested) ? multiplier * requested.length : 0,
        requestChars: multiplier && typeof parameters[0] === 'string' ? parameters[0].length : 0,
        failed: false
      }
      executions.push(entry)
      return entry
    }
    const observe = (entry: CrewSqlExecution, rows: SqliteRow[]) => {
      entry.rows += rows.length
      for (const row of rows) {
        entry.results.push(row)
        for (const value of Object.values(row)) {
          if (typeof value === 'string') {
            entry.stringChars += value.length
          }
        }
      }
      const serialized = JSON.stringify(rows)
      entry.chars += serialized.length
      entry.bytes += Buffer.byteLength(serialized)
    }
    const execute = <T>(entry: CrewSqlExecution, call: () => T): T => {
      try {
        control.before?.(sql)
        return call()
      } catch (error) {
        entry.failed = true
        throw error
      }
    }
    return {
      all: (...parameters) => {
        const entry = begin('all', parameters)
        return execute(entry, () => {
          const rows = statement.all(...parameters)
          observe(entry, rows)
          return rows
        })
      },
      get: (...parameters) => {
        const entry = begin('get', parameters)
        return execute(entry, () => {
          const row = statement.get(...parameters)
          observe(entry, row === undefined ? [] : [row])
          return row
        })
      },
      run: (...parameters) => execute(begin('run', parameters), () => statement.run(...parameters)),
      iterate: (...parameters) => {
        const entry = begin('iterate', parameters)
        const iterator = execute(entry, () => statement.iterate(...parameters))
        return (function* () {
          try {
            for (const row of iterator) {
              observe(entry, [row])
              yield row
            }
          } catch (error) {
            entry.failed = true
            throw error
          }
        })()
      },
      setReadBigInts: (enabled) => statement.setReadBigInts(enabled)
    }
  })
  return { executions, control, restore: () => spy.mockRestore() }
}

export function sqlTotals(executions: CrewSqlExecution[]) {
  return executions.reduce(
    (sum, row) => ({
      all: sum.all + Number(row.method === 'all'),
      get: sum.get + Number(row.method === 'get'),
      run: sum.run + Number(row.method === 'run'),
      iterate: sum.iterate + Number(row.method === 'iterate'),
      rows: sum.rows + row.rows,
      stringChars: sum.stringChars + row.stringChars,
      chars: sum.chars + row.chars,
      bytes: sum.bytes + row.bytes,
      selected: sum.selected + Number(selectedKeyMultiplier(row.sql) > 0),
      keys: sum.keys + row.keys,
      requestChars: sum.requestChars + row.requestChars,
      failed: sum.failed + Number(row.failed)
    }),
    {
      all: 0,
      get: 0,
      run: 0,
      iterate: 0,
      rows: 0,
      stringChars: 0,
      chars: 0,
      bytes: 0,
      selected: 0,
      keys: 0,
      requestChars: 0,
      failed: 0
    }
  )
}

export function crewQueryPlans(db: Database.Database, executions: readonly CrewSqlExecution[]) {
  const actual = executions.filter(
    (row) =>
      !row.failed && row.phase !== 'diagnostic' && (row.method === 'all' || row.method === 'get')
  )
  return {
    version: db.prepare('SELECT sqlite_version() AS version').get(),
    schema: db
      .prepare(
        'SELECT type, name, sql FROM sqlite_master WHERE sql IS NOT NULL ORDER BY type, name'
      )
      .all(),
    plans: actual.map(({ sql, parameters }) => ({
      sql,
      parameters,
      plan: db.prepare(`EXPLAIN QUERY PLAN ${sql}`).all(...parameters)
    }))
  }
}

import { mkdtempSync, rmSync } from 'node:fs'
import { tmpdir } from 'node:os'
import { join } from 'node:path'
import { afterEach, describe, expect, it } from 'vitest'
import Database from '../../../../sqlite/sync-database'
import { OrchestrationDb } from '../orchestration-db'
import { dropDerivedDeliverySchema } from './derived-delivery-test-fixture'
import { resolveOrchestrationMigrationStartVersion } from './orchestration-schema-version-skew'
import { createRootDispatch, reattachDispatchConsumer } from '../root-dispatch-test-fixture'
import { SCHEMA_VERSION } from '../contract-constants'

describe('derived delivery migration', () => {
  const connections: OrchestrationDb[] = []
  const directories: string[] = []
  afterEach(() => {
    for (const db of connections.splice(0)) {
      db.close()
    }
    for (const directory of directories.splice(0)) {
      rmSync(directory, { recursive: true, force: true })
    }
  })
  function open(path: string) {
    const db = new OrchestrationDb(path)
    connections.push(db)
    return db
  }
  function databasePath() {
    const directory = mkdtempSync(join(tmpdir(), 'orca-derived-delivery-'))
    directories.push(directory)
    return join(directory, 'orchestration.db')
  }

  it('preserves batch identity and terminal facts while removing a persisted wedge', () => {
    const path = databasePath()
    const original = open(path)
    const run = original.createRun({
      objective: 'upgrade',
      coordinatorHandle: 'coord',
      coordinatorPaneKey: 'tab:11111111-1111-4111-8111-111111111111'
    })
    const params = { runId: run.id, consumerGeneration: run.consumer_generation }
    const old = original.insertMessage({
      runId: run.id,
      from: 'worker',
      to: `run:${run.id}`,
      subject: 'old'
    })
    const batch = original.getDeliveryRaw(original.getOrCreateRunDelivery(params)!.delivery.id)!
    const next = original.insertMessage({
      runId: run.id,
      from: 'worker',
      to: `run:${run.id}`,
      subject: 'next'
    })
    connections.pop()!.close()
    const raw = new Database(path)
    dropDerivedDeliverySchema(raw)
    raw.prepare('UPDATE messages SET read = 1 WHERE id = ?').run(old.id)
    raw.exec(`
      INSERT INTO deliveries (id, run_id, mailbox_handle, consumer_generation, message_ids, status, created_at, acknowledged_at)
      VALUES ('history_ack', '${run.id}', 'run:${run.id}', 1, '[]', 'acknowledged', '2026-01-01 00:00:00', '2026-01-02 00:00:00'),
             ('history_fence', '${run.id}', 'run:${run.id}', 1, '[]', 'fenced', '2026-01-03 00:00:00', NULL);
    `)
    raw.pragma('user_version = 40')
    raw.close()
    const db = open(path)
    expect(db.getDeliveryRaw(batch.id)).toEqual(batch)
    expect(db.hasOutstandingRunDelivery(run.id)).toBe(false)
    expect(db.getDeliveryRaw('history_ack')).toMatchObject({
      acknowledged_at: '2026-01-02 00:00:00',
      status: 'acknowledged'
    })
    expect(db.getDeliveryRaw('history_fence')).toMatchObject({
      acknowledged_at: null,
      status: 'fenced'
    })
    expect(() => db.acknowledgeRunDelivery({ ...params, deliveryId: 'history_fence' })).toThrow(
      expect.objectContaining({ code: 'consumer_fenced' })
    )
    expect(db.getOrCreateRunDelivery(params)?.messages.map((message) => message.id)).toEqual([
      next.id
    ])
    expect(db.getDeliveryRaw(batch.id)?.acknowledged_at).toBeNull()
    expect(resolveOrchestrationMigrationStartVersion(db.db, SCHEMA_VERSION, SCHEMA_VERSION)).toBe(
      SCHEMA_VERSION
    )
    const reopened = open(path)
    expect(reopened.getOrCreateRunDelivery(params)?.messages.map((message) => message.id)).toEqual([
      next.id
    ])
  })

  it('shares a single batch across connections and rejects replaced consumers after it is consumed', () => {
    const path = databasePath()
    const first = open(path)
    const run = first.createRun({
      objective: 'connections',
      coordinatorHandle: 'coord',
      coordinatorPaneKey: 'tab:11111111-1111-4111-8111-111111111111'
    })
    const params = { runId: run.id, consumerGeneration: run.consumer_generation }
    const message = first.insertMessage({
      runId: run.id,
      from: 'worker',
      to: `run:${run.id}`,
      subject: 'one'
    })
    const second = open(path)
    const batch = first.getOrCreateRunDelivery(params)!
    expect(second.getOrCreateRunDelivery(params)?.delivery.id).toBe(batch.delivery.id)
    second.markAsRead([message.id])
    const replacement = second.bindRun({
      runId: run.id,
      coordinatorHandle: 'replacement',
      coordinatorPaneKey: 'other:22222222-2222-4222-9222-222222222222'
    })!
    expect(first.getDeliveryRaw(batch.delivery.id)).toMatchObject({
      status: 'fenced',
      acknowledged_at: null
    })
    first.insertMessage({ runId: run.id, from: 'worker', to: `run:${run.id}`, subject: 'next' })
    expect(() => first.getOrCreateRunDelivery(params)).toThrow(
      expect.objectContaining({ code: 'consumer_fenced' })
    )
    expect(() =>
      first.acknowledgeRunDelivery({ ...params, deliveryId: batch.delivery.id })
    ).toThrow(expect.objectContaining({ code: 'consumer_fenced' }))
    expect(
      second.getOrCreateRunDelivery({
        ...params,
        consumerGeneration: replacement.consumer_generation
      })?.messages[0].subject
    ).toBe('next')
  })

  it.each(['dispatch', 'attachment'] as const)(
    'fences a stale %s consumer across connections even after its batch is read',
    (consumerSource) => {
      const path = databasePath()
      const db = open(path)
      const run = db.createRun({
        objective: 'worker connections',
        coordinatorHandle: 'coord',
        coordinatorPaneKey: 'tab:11111111-1111-4111-8111-111111111111'
      })
      const dispatchId =
        consumerSource === 'dispatch'
          ? createRootDispatch(db, db.createTask({ spec: 'work', runId: run.id }).id, 'worker').id
          : 'ctx_remote'
      if (consumerSource === 'attachment') {
        db.createRemoteDispatchAttachment({
          runId: run.id,
          dispatchId,
          taskId: 'task_remote',
          homePeerFingerprint: 'peer',
          runtimeEpoch: 'epoch',
          protocolVersion: 1,
          mutationReceipt: {
            callerFingerprint: 'peer',
            requestId: 'attach',
            method: 'orchestration.federationAttachStart',
            payloadHash: 'hash'
          }
        })
      }
      const mailboxHandle = `dispatch:${dispatchId}`
      const message = db.insertMessage({
        runId: run.id,
        from: 'coord',
        to: mailboxHandle,
        subject: 'old'
      })
      const params = { runId: run.id, mailboxHandle, consumerGeneration: 0, consumerSource }
      const batch = db.getOrCreateMailboxDelivery(params)!
      const peer = open(path)
      peer.markAsRead([message.id])
      const authority = {
        dispatchId,
        paneKey: 'other:22222222-2222-4222-9222-222222222222',
        processIncarnation: 'worker:2'
      }
      if (consumerSource === 'dispatch') {
        reattachDispatchConsumer(peer, authority)
      } else {
        peer.prepareRemoteAttachmentAuthority({
          ...authority,
          worktreeId: 'folder',
          terminalHandle: 'replacement',
          setupState: 'not_applicable',
          effects: []
        })
      }
      expect(db.getDeliveryRaw(batch.delivery.id)).toMatchObject({
        status: 'fenced',
        acknowledged_at: null
      })
      peer.insertMessage({ runId: run.id, from: 'coord', to: mailboxHandle, subject: 'next' })
      expect(() => db.getOrCreateMailboxDelivery(params)).toThrow(
        expect.objectContaining({ code: 'consumer_fenced' })
      )
      expect(() =>
        db.acknowledgeMailboxDelivery({ ...params, deliveryId: batch.delivery.id })
      ).toThrow(expect.objectContaining({ code: 'consumer_fenced' }))
      expect(
        peer.getOrCreateMailboxDelivery({ ...params, consumerGeneration: 1 })?.messages[0].subject
      ).toBe('next')
    }
  )
})

import type { OrchestrationDb } from '../orchestration-db'

// Drop derived triggers/views before hand-editing deliveries; reopening recreates them.
export function dropDerivedDeliverySchema(db: OrchestrationDb['db']): void {
  db.exec(
    'DROP TRIGGER IF EXISTS trg_deliveries_one_outstanding; DROP VIEW IF EXISTS outstanding_deliveries;'
  )
}

