// Merge Claude Code 2.1.280 PTY hook captures with their cancel/kill sidecars in time order.
import { readFileSync } from 'node:fs'
import { join } from 'node:path'
import { z } from 'zod'
import { AGENT_INTERRUPT_SETTLE_MS } from '../../../../../shared/agent-status/lifecycle/agent-interrupt-intent'

const capturedHook = z.object({
  kind: z.literal('hook'),
  t: z.number(),
  index: z.number().int().nonnegative(),
  sleep_procs: z.array(z.string()),
  payload: z.record(z.string(), z.unknown())
})
const capturedCancel = z.object({
  kind: z.literal('cancel'),
  t: z.number(),
  label: z.string(),
  interrupted_painted: z.boolean(),
  hooks_before_next_typed_prompt: z.array(z.number().int().nonnegative())
})
const capturedKill = z.object({ kind: z.literal('kill'), t: z.number(), needle: z.string() })
const capturedRecord = z.discriminatedUnion('kind', [capturedHook, capturedCancel, capturedKill])

export type CapturedHook = z.infer<typeof capturedHook>
export type CapturedCancel = z.infer<typeof capturedCancel>
export type CapturedKill = z.infer<typeof capturedKill>
export type CapturedRecord = z.infer<typeof capturedRecord>

export function loadCapture(name: string): CapturedRecord[] {
  return readFileSync(
    join(__dirname, '..', '..', '..', '..', '..', 'shared', '__fixtures__', `${name}.jsonl`),
    'utf8'
  )
    .trim()
    .split('\n')
    .map((line) => capturedRecord.parse(JSON.parse(line)))
}

export function hookAt(records: CapturedRecord[], index: number): CapturedHook {
  const hook = records.find((record) => record.kind === 'hook' && record.index === index)
  if (hook?.kind !== 'hook') {
    throw new Error(`Captured hook ${index} not found`)
  }
  return hook
}

export function cancelLabelled(records: CapturedRecord[], label: string): CapturedCancel {
  const cancel = records.find((record) => record.kind === 'cancel' && record.label === label)
  if (cancel?.kind !== 'cancel') {
    throw new Error(`Captured cancel ${label} not found`)
  }
  return cancel
}

/** A hook inside the capture's settle window supersedes the renderer's inferred cancellation. */
export function hookSupersedesCancel(records: CapturedRecord[], cancel: CapturedCancel): boolean {
  return records.some(
    (record) =>
      record.kind === 'hook' &&
      record.t > cancel.t &&
      (record.t - cancel.t) * 1000 < AGENT_INTERRUPT_SETTLE_MS
  )
}

import { readFileSync } from 'node:fs'
import { join } from 'node:path'
import { z } from 'zod'
import { extractAllOscTitleEntries } from '../../../../../shared/agent-status/title/osc-title-extraction'

const captureEvent = z.discriminatedUnion('kind', [
  z.object({ kind: z.literal('title'), title: z.string(), atMs: z.number() }),
  z.object({ kind: z.literal('input'), text: z.string(), label: z.string(), atMs: z.number() })
])

export function loadClaudeInterruptCapture(name: string) {
  const base = join(__dirname, '../../../../runtime/__fixtures__', `claude-interrupt-${name}`)
  const transcript = readFileSync(`${base}.txt`, 'utf8')
  const events = z.array(captureEvent).parse(JSON.parse(readFileSync(`${base}.input.json`, 'utf8')))
  const titleEntries = extractAllOscTitleEntries(transcript)
  const titles = titleEntries.map((entry) => entry.title)
  const recordedTitles = events.flatMap((event) => (event.kind === 'title' ? [event.title] : []))
  if (JSON.stringify(titles) !== JSON.stringify(recordedTitles)) {
    throw new Error('Capture timeline must match the raw PTY title frames in byte order')
  }
  let offset = 0
  let titleIndex = 0
  return events.map((event) => {
    if (event.kind === 'input') {
      return event
    }
    const entry = titleEntries[titleIndex++]
    if (!entry) {
      throw new Error('Captured OSC title frame missing from transcript')
    }
    const end = entry.end
    const chunk = transcript.slice(offset, end)
    offset = end
    return { ...event, chunk }
  })
}

import { existsSync, mkdirSync } from 'node:fs'
import { dirname } from 'node:path'

import SyncDatabase from '../../../../sqlite/sync-database'
import { lastStatusDatabasePath } from '../../last-status-store'
import { assemble } from '../../last-status-saved-rows'

/** What a restart restores, in the last-status file shape, read straight from the saved rows. */
export function readSavedStatus(lastStatusPath: string): string {
  const db = new SyncDatabase(lastStatusDatabasePath(lastStatusPath), {
    readonly: true,
    fileMustExist: true
  })
  try {
    const rows = db
      .prepare('SELECT key, value FROM rows ORDER BY seq')
      .all()
      .map((row) => ({ key: String(row.key), json: String(row.value) }))
    const { agentExits, ...file } = assemble(rows)
    return JSON.stringify(agentExits.length > 0 ? { ...file, agentExits } : file)
  } finally {
    db.close()
  }
}

export function hasSavedStatus(lastStatusPath: string): boolean {
  if (!existsSync(lastStatusDatabasePath(lastStatusPath))) {
    return false
  }
  return Object.keys(JSON.parse(readSavedStatus(lastStatusPath)).entries).length > 0
}

/** Another connection holding the write lock, as a second process would. */
export function holdSavedStatusLock(lastStatusPath: string): () => void {
  mkdirSync(dirname(lastStatusPath), { recursive: true })
  const db = new SyncDatabase(lastStatusDatabasePath(lastStatusPath))
  db.exec('BEGIN EXCLUSIVE')
  return () => {
    db.exec('ROLLBACK')
    db.close()
  }
}

