    mode: 'create',
    resultSchemaVersion: 1,
    maxCaptureBytes,
    signal,
    onStdout: (chunk) => stdoutChunks.push(chunk),
    onStderr: (chunk) => stderrChunks.push(chunk),
    // oxlint-disable-next-line typescript/consistent-type-assertions -- SAFETY: The fixture implements every child member used by runRecipeCommand.
    spawnCommand: vi.fn(() => child) as never
  })
  return { child, result, stdoutChunks, stderrChunks }
}

describe('recipe output capture', () => {
  it('does not restore bytes discarded at an earlier chunk boundary', async () => {
    const fixture = fakeCommand(5)
    for (const chunk of ['😀', 'ab', 'c']) {
      fixture.child.stdout.emit('data', Buffer.from(chunk, 'utf8'))
    }
    fixture.child.emit('close', 0, null)
    await expect(fixture.result).resolves.toMatchObject({ stdout: 'abc' })
  })

  it('returns the captured tails when cancellation needs force-kill', async () => {
    vi.useFakeTimers()
    const controller = new AbortController()
    const fixture = fakeCommand(6, controller.signal)
    fixture.child.stdout.emit('data', Buffer.from('abc😀Z'))
    fixture.child.stderr.emit('data', Buffer.from('error tail'))
    controller.abort()
    fixture.child.stdout.emit('data', Buffer.from('!'))
    await vi.advanceTimersByTimeAsync(5000)
    await expect(fixture.result).resolves.toEqual({
      stdout: '😀Z!',
      stderr: 'r tail',
      exitCode: null,
      signal: null,
      aborted: true
    })
    expect(fixture.child.kill.mock.calls).toEqual([['SIGTERM'], ['SIGKILL']])
    expect(fixture.child.unref).toHaveBeenCalledOnce()
  })
})

import { mkdtempSync, readFileSync, writeFileSync } from 'node:fs'
import { tmpdir } from 'node:os'
import { join } from 'node:path'
import { removeTempDirs } from '../../testing/remove-temp-dirs.test-support'
import { afterEach, describe, expect, it, vi } from 'vitest'
import { runRecipeCommand } from './ephemeral-vm-recipe-process'

const tmpRoots: string[] = []

afterEach(async () => {
  vi.useRealTimers()
  await removeTempDirs(tmpRoots.splice(0))
})

function makeRepo(): string {
  const root = mkdtempSync(join(tmpdir(), 'orca-vm-recipe-process-'))
  tmpRoots.push(root)
  return root
}

function nodeCommand(scriptPath: string): string {
  return `"${process.execPath}" "${scriptPath}"`
}

function isAlive(pid: number): boolean {
  try {
    process.kill(pid, 0)
    return true
  } catch {
    return false
  }
}

describe('runRecipeCommand', () => {
  it.skipIf(process.platform === 'win32')(
    'kills grandchildren of a recipe that outlives its timeout',
    async () => {
      const repoPath = makeRepo()
      const sleeperPath = join(repoPath, 'sleeper.js')
      const spawnerPath = join(repoPath, 'spawner.js')
      const pidPath = join(repoPath, 'grandchild.pid')
      writeFileSync(sleeperPath, 'setInterval(() => {}, 1000)\n')
      writeFileSync(
        spawnerPath,
        [
          "const { spawn } = require('node:child_process')",
          `const child = spawn(process.execPath, [${JSON.stringify(sleeperPath)}], { stdio: 'ignore' })`,
          `require('node:fs').writeFileSync(${JSON.stringify(pidPath)}, String(child.pid))`,
          "process.stderr.write('ready\\n')",
          'setInterval(() => {}, 1000)'
        ].join('\n')
      )
      // Fake only the deadline timers so the timeout fires after the grandchild exists, even under load.
      vi.useFakeTimers({ toFake: ['setTimeout', 'clearTimeout'] })
      const ready = Promise.withResolvers<void>()

      const resultPromise = runRecipeCommand({
        command: nodeCommand(spawnerPath),
        repoPath,
        mode: 'create',
        resultSchemaVersion: 1,
        context: { recipeId: 'cloud-sandbox', repoPath },
        timeoutMs: 1_000,
        onStderr: (chunk) => {
          if (chunk.includes('ready')) {
            ready.resolve()
          }
        }
      })
      await ready.promise
      await vi.advanceTimersByTimeAsync(1_000)
      const result = await resultPromise
      vi.useRealTimers()

      expect(result).toMatchObject({ timedOut: true })
      expect(result).not.toHaveProperty('aborted')
      const grandchildPid = Number(readFileSync(pidPath, 'utf8'))
      await vi.waitFor(() => expect(isAlive(grandchildPid)).toBe(false), { timeout: 2_000 })
    },
    10_000
  )
})

